head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.procJob = "";
scwin.logicPackYn = "Y";
scwin.clickBzProcsNo = ""; // 업무처리번호 (클릭된)
scwin.clickListBzTpCd = ""; // 상장업무구분코드 (그리드 로우 클릭시 상장업무구분코드를 획득함)
scwin.clickIsuCd = ""; // 종목코드(클릭된)
scwin.clickAddIsuRnd = ""; // 추가상장차수(클릭된)
scwin.clickListEtpProdTpCd = ""; // ETP상품구분코드(클릭된)
scwin.vListInit = true;
scwin.logicPackYn = "Y";

// 화면ID

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode(); // 발행기관
        $c.etrc.fn_SetRetTypeCombo(dts_RetTp); // 심사반송구분코드
        MaxTab_01.setSelectedTabIndex(1);
        $c.cm.PanelToGroupBox(panel_Top);
        btn_LgcChk.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_RcvPrc_onclick
 * @description btn_RcvPrc 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RcvPrc_onclick = async function() {
    try {
        /*if ( js_svrGubun == 'dr') {
        		alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        		return;
        }*/
        await scwin.packacpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08001.btn_RcvPrc_onclick" });
    }
};

/**
         * @method
         * @name btn_RetPrc_onclick
         * @description btn_RetPrc 클릭 이벤트
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.btn_RetPrc_onclick = async function() {
    try {
        if (MaxTab_01.getSelectedTabIndex() === "1" || MaxTab_01.getSelectedTabIndex() === "2") {
            if (cmb_RETN_BZ_TP_CD.getValue() === "02") {
                await $c.win.alert("해당사유는 손실제한 ETN일때만 선택가능합니다.");
                cmb_RETN_BZ_TP_CD.focus();
                return;
            }
        }
        await scwin.packret();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08001.btn_RetPrc_onclick" });
    }
};

/**
 * @method
 * @name cmb_ISUR_CD_OnSelChange
 * @description cmb_ISUR_CD 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_OnSelChange = async function() {
    try {
        // 발행회사 조회시 초기에 재조회 안타게 하기 위함
        if (scwin.vListInit === false) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08001.cmb_ISUR_CD_OnSelChange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08001.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // Download excel data
        $c.stf.doLogSave("ULDSTF08001.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08001.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_1_OnHeadCheckClick
 * @description grd List 1 On Head Check Click 처리
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_OnHeadCheckClick = function(col, colid, bCheck) {
    try {
        // 신규상장접수 > 헤드체크박스 클릭
        $c.lce.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08001.grd_List_1_OnHeadCheckClick" });
    }
};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = function(row, colid) {
    try {
        // 신규상장접수 > Grid Row Click
        if (colid === 'ISU_ABBRV') {
            scwin.openNewWin(row, dts_List_1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08001.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
