};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === "3") {
            // 신규상장접수(손실제한)
            btn_LgcChk.show("");
        } else {
            btn_LgcChk.hide();
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08001.MaxTab_01_OnSelChanged" });
    }
};

