///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 발행회사 콤보박스 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EtnInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description 상장신청접수 에 대한 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    // if (!fn_CheckSearchForm()) { alert("신청구분을 선택하셔야 합니다!"); return; }

    let v_listBzTpCd = ""; // 심사청구,상장신청 구분코드
    scwin.vListInit = false; // 처음 화면 로딩시 두 번 리스트 조회 안타게 하기 위함.

    // 신규상장접수
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        if (cmb_LIST_BZ_TP_CD.getValue() === "1") {
            v_listBzTpCd = "701"; // 예비심사청구

        } else if (cmb_LIST_BZ_TP_CD.getValue() === "2") {
            v_listBzTpCd = "702"; // 신규상장신청

        }
        url += "?SCREN_ID=" + "ULDSTF08001.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnReceiptRcv";
        url += "&inputMessageId=ETN_LISTEDRCV_SEARCH_OUT";
        url += "&ISUR_CD=" + cmb_ISUR_CD.getValue();
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/etn/EtnListedRcv.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 추가상장접수

