/**
 * @method
 * @name packacpt
 * @description 접수 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.packacpt = async function() {
    let dtsObj = scwin.getDataSet();
    let vSelectCnt = scwin.selectIsuCheckCnt(dtsObj);
    if (vSelectCnt === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!$c.etrc.fn_CheckForm("1")) {
        return;
    }

    // procJob = ' 선택한 '+vSelectCnt+'종목에 대한 접수처리 ';
    scwin.procJob = ' 선택한 종목에 대한 일괄접수처리 ';
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        // 선택한 종목에 대하여 '접수' 상태 변경
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "CHECK") === "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_10);
            }
        }
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_3)";
        } else if (MaxTab_01.getSelectedTabIndex() === 4) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_4)";
        }
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/etn/EtnListedRcv.do",
            ref : "",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name packret
 * @description 반송 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.packret = async function() {
    let dtsObj = scwin.getDataSet();
    let vSelectCnt = scwin.selectIsuCheckCnt(dtsObj);
    if (vSelectCnt === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!$c.etrc.fn_CheckForm("2")) {
        return;
    }

    // procJob = ' 선택한 '+vSelectCnt+'종목에 대한 반송처리 ';
    scwin.procJob = ' 선택한 종목에 대한 일괄반송처리 ';
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        // 선택한 종목에 대하여 '반송' 상태 변경
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "CHECK") === "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_02);
                dtsObj.setCellData(i, "RET_RSN_CD", cmb_RETN_BZ_TP_CD.getValue());
                dtsObj.setCellData(i, "RET_RSN", cmb_RETN_BZ_TP_CD.getValue() + ":" + txb_RET_RSN.getValue());
            }
        }
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            // 신규상장접수(일반)
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            // 추가상장접수
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            // 신규상장접수(손실제한)
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_3)";
        } else if (MaxTab_01.getSelectedTabIndex() === 4) {
            // 추가상장접수(손실제한)
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_4)";
        }
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/etn/EtnListedRcv.do",
            ref : "",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        txb_RET_RSN.setValue(""); // 초기화

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSearchForm
 * @description 필요한 경우 넣으면 됨(신청구분 선택하기 위한 폼체크이나 불필요함
 * @returns {void}
 * @hidden N
 */
scwin.checkSearchForm = function() {
    let bCheckForm = true;
    if (cmb_ISUR_CD.getValue() === "") {
        bCheckForm = false;
    }
    return bCheckForm;
};

/**
 * @method
 * @name setBzProcsNo
 * @description (신규접수)클릭된 그리드에 대한 업무처리번호 획득
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
    scwin.clickListBzTpCd = dtsObj.getCellData(Number(obj), "LIST_BZ_TP_CD");
    scwin.clickListEtpProdTpCd = dtsObj.getCellData(Number(obj), "ETP_PROD_TP_CD");

    // 추가상장인 경우
    if (MaxTab_01.getSelectedTabIndex() === 2 || MaxTab_01.getSelectedTabIndex() === 4) {
        scwin.clickIsuCd = dtsObj.getCellData(Number(obj), "ISU_CD");
        scwin.clickAddIsuRnd = dtsObj.getCellData(Number(obj), "ADD_ISU_RND");
    }
};

/**
 * @method
 * @name openNewWin
 * @description 상장신청접수 에 대한 상세 팝업조회
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.openNewWin = function(row, dtsObj) {
    if (row > 0) {
        // 그리드에서 선택시
        // 획득 업무처리번호, 상장업무구분코드
        scwin.setBzProcsNo(row, dtsObj);
        $c.etrc.fn_OpenDetailRecv(scwin.clickListBzTpCd, scwin.clickListEtpProdTpCd);
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "신규상장접수(일반)목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "추가상장접수(일반)목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        $c.data.downloadGridViewExcel(grd_List_3, {fileName: "신규상장접수(손실제한)목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        $c.data.downloadGridViewExcel(grd_List_4, {fileName: "추가상장접수(손실제한)목록", type: "8"});
    }
};

/**
 * @method
 * @name getDataSet
 * @description Tab에 따른 Dataset 가져오기
 * @returns {void}
 * @hidden N
 */
scwin.getDataSet = function() {
    let dtsObj;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dtsObj = dts_List_2;
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        dtsObj = dts_List_3;
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        dtsObj = dts_List_4;
    }
    return dtsObj;
};

/**
 * @method
 * @name selectIsuCheckCnt
 * @description Tab에 따른 Dataset 가져오기
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.selectIsuCheckCnt = function(dtsObj) {
    let k = 0;
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "CHECK") === "T") {
            k++;
        }
    }
    return k;
};

